tx('valanciunas-sacramento','2025-02-05','Sacramento repackages part of the return.','Cissoko and the Denver second from the Fox exchange join Sacramento’s 2029 second. Washington sends Valančiūnas in return.','SAC WAS',ms('valanciunas','WAS','SAC')+ms('cissoko w3-den28-fox-second sac29-cj-second','SAC','WAS'),'w3-valanciunas25 w3-valanciunas25-picks w3-kings25-guide',notes=['The Kings media guide dates completion February 5. The Denver pick conveys only at positions 34–60.'],short='Valančiūnas joins Sacramento')
tx('valanciunas-denver','2025-07-13','Denver and Sacramento exchange centers.','Valančiūnas moves to Denver for Šarić. The final exchange includes no additional draft consideration.','SAC DEN',ms('valanciunas','SAC','DEN')+ms('saric','DEN','SAC'),'w3-valanciunas-denver w3-summer25',notes=['July 13 is the official completed-trade date. July 1 was the reported agreement. Šarić’s intervening career after Minnesota is outside this route.'],short='Valančiūnas joins Denver')
